import os, json, shutil, hashlib
root = "E:\\0zhongqi"
q = os.path.join(root, "_QUARANTINE_20261027")
def sha1(p):
    h = hashlib.sha1()
    with open(p, "rb") as f:
        for b in iter(lambda: f.read(1048576), b""):
            h.update(b)
    return h.hexdigest()[:12]
known = set()
for base in ("zhongqi_out", "zhongqi-arena_out"):
    for dp, dn, fn in os.walk(os.path.join(root, base)):
        for f in fn:
            try: known.add(sha1(os.path.join(dp, f)))
            except Exception: pass
actions = []
for name in sorted(os.listdir(root)):
    p = os.path.join(root, name)
    if not os.path.isdir(p): continue
    if not name.startswith("zhongqi-"): continue
    if name.endswith("deliverable"): continue
    allfiles = []
    for dp, dn, fn in os.walk(p):
        for f in fn:
            allfiles.append(os.path.join(dp, f))
    real = [x for x in allfiles if not os.path.basename(x).startswith("~$")]
    ok = True
    for x in real:
        try:
            if sha1(x) not in known: ok = False; break
        except Exception: ok = False; break
    if ok and real:
        dst = os.path.join(q, "_DUP_" + name)
        base = dst; i = 2
        while os.path.exists(base):
            base = dst + "_" + str(i); i += 1
        shutil.move(p, base)
        actions.append(["QUARANTINED-DUP", name, len(real)])
    else:
        actions.append(["KEPT", name, len(real)])
killed = []
for dp, dn, fn in os.walk(root):
    if dp == q or dp.startswith(q + os.sep): continue
    for f in fn:
        if f.startswith("~$"):
            try: os.remove(os.path.join(dp, f)); killed.append(os.path.join(dp, f))
            except Exception: pass
final = []
for name in sorted(os.listdir(root)):
    p = os.path.join(root, name)
    if os.path.isdir(p):
        tot = 0; n = 0
        for dp2, dn2, fn2 in os.walk(p):
            for f in fn2:
                try: tot += os.path.getsize(os.path.join(dp2, f)); n += 1
                except Exception: pass
        final.append([name, "DIR", round(tot/1048576, 1), n])
    else:
        final.append([name, "FILE", round(os.path.getsize(p)/1048576, 2)])
print(json.dumps({"actions": actions, "killed": killed, "final": final}, ensure_ascii=True))
